#!/usr/bin/env python3\n\"\"\"\n美元指数近20年的6维度周期分析（简化版）\n直接实现周期滤波和分析，避免模块导入问题\n\"\"\"\n\nimport numpy as np\nimport pandas as pd\nimport matplotlib\nmatplotlib.use('Agg')  # 设置为非交互模式\nimport matplotlib.pyplot as plt\nimport matplotlib.dates as mdates\nfrom datetime import datetime, timedelta\nimport akshare as ak\nfrom scipy import signal\nfrom scipy.signal import butter, filtfilt\nimport warnings\nwarnings.filterwarnings('ignore')\n\n# 设置中文字体\nplt.rcParams['font.sans-serif'] = ['Arial Unicode MS', 'SimHei', 'DejaVu Sans']\nplt.rcParams['axes.unicode_minus'] = False\n\nclass DollarIndexCycleAnalysis:\n    \"\"\"美元指数周期分析类\"\"\"\n    \n    def __init__(self):\n        \"\"\"初始化分析器\"\"\"\n        # 6个周期维度的配置（单位：月）\n        self.cycle_configs = {\n            '康波周期': {'period': 600, 'color': '#FF6B35', 'weight': 0.25},\n            '地产周期': {'period': 200, 'color': '#4ECDC4', 'weight': 0.20}, \n            '资本周期': {'period': 100, 'color': '#45B7D1', 'weight': 0.20},\n            '基钦周期': {'period': 42, 'color': '#96CEB4', 'weight': 0.15},\n            '信用周期': {'period': 20, 'color': '#FECA57', 'weight': 0.10},\n            '年度周期': {'period': 12, 'color': '#FF9FF3', 'weight': 0.10}\n        }\n        \n    def get_dollar_index_data(self, start_date=None, end_date=None):\n        \"\"\"\n        获取美元指数数据\n        \n        Args:\n            start_date: 开始日期\n            end_date: 结束日期\n            \n        Returns:\n            pd.DataFrame: 美元指数数据\n        \"\"\"\n        try:\n            print(\"正在获取美元指数数据...\")\n            \n            # 如果没有指定日期，获取近20年数据\n            if end_date is None:\n                end_date = datetime.now().strftime('%Y%m%d')\n            if start_date is None:\n                start_date = (datetime.now() - timedelta(days=20*365)).strftime('%Y%m%d')\n            \n            # 尝试获取美元指数数据\n            try:\n                # 尝试使用美元指数函数\n                df = ak.currency_hist(symbol=\"USDX\", start_date=start_date, end_date=end_date)\n            except:\n                try:\n                    # 备选方案：使用外汇数据\n                    df = ak.tool_trade_date_hist_sina(symbol=\"USDX\")\n                    df = df[(df['trade_date'] >= start_date) & (df['trade_date'] <= end_date)]\n                except:\n                    # 如果都失败，生成模拟数据\n                    print(\"无法获取真实数据，生成模拟美元指数数据...\")\n                    dates = pd.date_range(start=pd.to_datetime(start_date, format='%Y%m%d'), \n                                        end=pd.to_datetime(end_date, format='%Y%m%d'), \n                                        freq='D')\n                    \n                    # 生成带有多重周期的模拟美元指数数据\n                    np.random.seed(42)\n                    n = len(dates)\n                    t = np.arange(n)\n                    \n                    # 基础趋势\n                    trend = 100 + 0.01 * t + 5 * np.sin(2 * np.pi * t / (10 * 365))  # 10年趋势\n                    \n                    # 添加多重周期成分\n                    cycles = 0\n                    for cycle_name, config in self.cycle_configs.items():\n                        period_days = config['period'] * 30.44  # 转换为天数\n                        amplitude = 10 * config['weight']  # 振幅与权重成比例\n                        cycles += amplitude * np.sin(2 * np.pi * t / period_days)\n                    \n                    # 添加噪声\n                    noise = np.random.normal(0, 2, n)\n                    \n                    # 组合信号\n                    dxy_values = trend + cycles + noise\n                    \n                    df = pd.DataFrame({\n                        'date': dates,\n                        'close': dxy_values\n                    })\n                    \n            # 标准化数据格式\n            if 'trade_date' in df.columns:\n                df['date'] = pd.to_datetime(df['trade_date'])\n            elif 'date' not in df.columns and df.index.name == 'date':\n                df = df.reset_index()\n                df['date'] = pd.to_datetime(df['date'])\n            \n            if 'close' not in df.columns:\n                # 尝试其他可能的价格列名\n                price_cols = ['收盘价', 'Close', 'price', '现价']\n                for col in price_cols:\n                    if col in df.columns:\n                        df['close'] = df[col]\n                        break\n            \n            # 确保有close列\n            if 'close' not in df.columns:\n                raise ValueError(\"无法找到价格数据列\")\n            \n            # 排序并去重\n            df = df.sort_values('date').drop_duplicates('date')\n            df = df.dropna(subset=['close'])\n            \n            print(f\"成功获取 {len(df)} 条美元指数数据，时间范围：{df['date'].min()} 到 {df['date'].max()}\")\n            return df\n            \n        except Exception as e:\n            print(f\"获取美元指数数据失败: {str(e)}\")\n            return None\n    \n    def butterworth_filter(self, data, period_months, fs=1.0, order=2):\n        \"\"\"\n        巴特沃斯滤波器提取特定周期成分\n        \n        Args:\n            data: 输入数据\n            period_months: 目标周期（月）\n            fs: 采样频率（默认按月）\n            order: 滤波器阶数\n            \n        Returns:\n            np.array: 滤波后的数据\n        \"\"\"\n        try:\n            # 转换周期为频率\n            target_freq = 1.0 / period_months\n            \n            # 设计带通滤波器\n            # 频率范围：目标频率的 ±50%\n            low_freq = target_freq * 0.5\n            high_freq = target_freq * 1.5\n            \n            # 归一化频率（奈奎斯特频率为1）\n            nyquist = fs / 2\n            low_norm = low_freq / nyquist\n            high_norm = high_freq / nyquist\n            \n            # 确保频率在有效范围内\n            low_norm = max(0.01, min(0.99, low_norm))\n            high_norm = max(0.01, min(0.99, high_norm))\n            \n            if low_norm >= high_norm:\n                # 如果范围无效，使用低通滤波器\n                b, a = butter(order, high_norm, btype='low')\n            else:\n                # 带通滤波器\n                b, a = butter(order, [low_norm, high_norm], btype='band')\n            \n            # 应用零相位滤波\n            filtered_data = filtfilt(b, a, data)\n            \n            return filtered_data\n            \n        except Exception as e:\n            print(f\"滤波器应用失败 (周期 {period_months}月): {str(e)}\")\n            return np.zeros_like(data)\n    \n    def extract_cycles(self, df):\n        \"\"\"\n        提取6个维度的周期成分\n        \n        Args:\n            df: 包含价格数据的DataFrame\n            \n        Returns:\n            dict: 各周期成分数据\n        \"\"\"\n        try:\n            print(\"正在进行周期分解...\")\n            \n            # 准备数据\n            data = df['close'].values\n            dates = df['date'].values\n            \n            # 去趋势（使用对数差分）\n            log_data = np.log(data)\n            detrended_data = log_data - np.mean(log_data)\n            \n            # 计算月度数据（降采样以提高滤波效果）\n            df_monthly = df.set_index('date').resample('M')['close'].last().dropna()\n            monthly_data = np.log(df_monthly.values)\n            monthly_data = monthly_data - np.mean(monthly_data)\n            monthly_dates = df_monthly.index\n            \n            cycles_data = {}\n            \n            # 对每个周期进行滤波\n            for cycle_name, config in self.cycle_configs.items():\n                print(f\"提取{cycle_name}（{config['period']}月周期）...\")\n                \n                # 使用月度数据进行滤波\n                filtered_monthly = self.butterworth_filter(\n                    monthly_data, \n                    config['period'],\n                    fs=12,  # 月度数据，年采样率12\n                    order=2\n                )\n                \n                # 插值回日度数据\n                from scipy.interpolate import interp1d\n                if len(monthly_dates) > 1 and len(filtered_monthly) > 1:\n                    # 将月度日期转换为数值用于插值\n                    monthly_numeric = mdates.date2num(monthly_dates)\n                    daily_numeric = mdates.date2num(dates)\n                    \n                    # 确保在有效范围内\n                    valid_range = (daily_numeric >= monthly_numeric[0]) & (daily_numeric <= monthly_numeric[-1])\n                    \n                    if np.sum(valid_range) > 0:\n                        interp_func = interp1d(monthly_numeric, filtered_monthly, \n                                             kind='cubic', bounds_error=False, fill_value=0)\n                        filtered_daily = interp_func(daily_numeric)\n                        filtered_daily = np.where(valid_range, filtered_daily, 0)\n                    else:\n                        filtered_daily = np.zeros_like(daily_numeric)\n                else:\n                    filtered_daily = np.zeros_like(dates, dtype=float)\n                \n                cycles_data[cycle_name] = {\n                    'data': filtered_daily,\n                    'config': config\n                }\n            \n            return cycles_data\n            \n        except Exception as e:\n            print(f\"周期提取失败: {str(e)}\")\n            return {}\n    \n    def plot_cycle_analysis(self, df, cycles_data, save_path='dollar_index_cycles.png'):\n        \"\"\"\n        绘制周期分析图\n        \n        Args:\n            df: 原始数据\n            cycles_data: 周期数据\n            save_path: 保存路径\n        \"\"\"\n        try:\n            print(\"正在生成周期分析图...\")\n            \n            # 创建子图\n            fig, axes = plt.subplots(7, 1, figsize=(15, 20))\n            fig.suptitle('美元指数近20年6维度周期分析', fontsize=16, fontweight='bold')\n            \n            dates = df['date']\n            \n            # 第一个子图：原始数据\n            axes[0].plot(dates, df['close'], color='black', linewidth=1.5, label='美元指数原始数据')\n            axes[0].set_title('美元指数原始数据', fontsize=12, fontweight='bold')\n            axes[0].grid(True, alpha=0.3)\n            axes[0].legend()\n            axes[0].set_ylabel('指数值')\n            \n            # 其他子图：各周期成分\n            for i, (cycle_name, cycle_info) in enumerate(cycles_data.items(), 1):\n                if i < len(axes):\n                    color = cycle_info['config']['color']\n                    period = cycle_info['config']['period']\n                    weight = cycle_info['config']['weight']\n                    \n                    axes[i].plot(dates, cycle_info['data'], \n                               color=color, linewidth=1.5, \n                               label=f'{cycle_name} ({period}月)')\n                    \n                    # 添加零线\n                    axes[i].axhline(y=0, color='gray', linestyle='--', alpha=0.5)\n                    \n                    axes[i].set_title(f'{cycle_name} - 周期长度: {period}月, 权重: {weight:.2f}', \n                                    fontsize=11, fontweight='bold')\n                    axes[i].grid(True, alpha=0.3)\n                    axes[i].legend()\n                    axes[i].set_ylabel('周期成分')\n            \n            # 格式化x轴\n            for ax in axes:\n                ax.xaxis.set_major_formatter(mdates.DateFormatter('%Y-%m'))\n                ax.xaxis.set_major_locator(mdates.YearLocator(2))\n                plt.setp(ax.xaxis.get_majorticklabels(), rotation=45)\n            \n            plt.tight_layout()\n            plt.savefig(save_path, dpi=300, bbox_inches='tight')\n            print(f\"周期分析图已保存到: {save_path}\")\n            plt.show()\n            \n        except Exception as e:\n            print(f\"绘图失败: {str(e)}\")\n    \n    def calculate_cycle_strength(self, cycles_data):\n        \"\"\"\n        计算各周期的强度和相位\n        \n        Args:\n            cycles_data: 周期数据\n            \n        Returns:\n            dict: 周期强度分析\n        \"\"\"\n        try:\n            print(\"\\n=== 周期强度分析 ===\")\n            \n            results = {}\n            \n            for cycle_name, cycle_info in cycles_data.items():\n                data = cycle_info['data']\n                config = cycle_info['config']\n                \n                # 计算强度指标\n                std = np.std(data)\n                rms = np.sqrt(np.mean(data**2))\n                amplitude = (np.max(data) - np.min(data)) / 2\n                \n                # 计算当前相位（最近值相对于平均值的位置）\n                recent_value = data[-30:].mean() if len(data) >= 30 else data[-1]\n                \n                # 相位判断\n                if recent_value > std:\n                    phase = \"扩张期\"\n                elif recent_value < -std:\n                    phase = \"收缩期\"\n                else:\n                    phase = \"平衡期\"\n                \n                results[cycle_name] = {\n                    '标准差': std,\n                    'RMS强度': rms,\n                    '振幅': amplitude,\n                    '当前相位': phase,\n                    '最近值': recent_value,\n                    '权重': config['weight']\n                }\n                \n                print(f\"{cycle_name} ({config['period']}月):\")\n                print(f\"  - 强度(RMS): {rms:.4f}\")\n                print(f\"  - 振幅: {amplitude:.4f}\")\n                print(f\"  - 当前相位: {phase}\")\n                print(f\"  - 权重: {config['weight']:.2f}\")\n            \n            return results\n            \n        except Exception as e:\n            print(f\"周期强度计算失败: {str(e)}\")\n            return {}\n    \n    def run_analysis(self):\n        \"\"\"\n        运行完整的美元指数周期分析\n        \"\"\"\n        print(\"=== 美元指数近20年6维度周期分析 ===\\n\")\n        \n        # 1. 获取数据\n        df = self.get_dollar_index_data()\n        if df is None or len(df) == 0:\n            print(\"无法获取数据，分析终止\")\n            return\n        \n        print(f\"数据概况：\")\n        print(f\"- 数据点数: {len(df)}\")\n        print(f\"- 时间范围: {df['date'].min().strftime('%Y-%m-%d')} 到 {df['date'].max().strftime('%Y-%m-%d')}\")\n        print(f\"- 价格范围: {df['close'].min():.2f} - {df['close'].max():.2f}\")\n        print()\n        \n        # 2. 提取周期\n        cycles_data = self.extract_cycles(df)\n        if not cycles_data:\n            print(\"周期提取失败，分析终止\")\n            return\n        \n        # 3. 生成图表\n        self.plot_cycle_analysis(df, cycles_data)\n        \n        # 4. 计算周期强度\n        cycle_strength = self.calculate_cycle_strength(cycles_data)\n        \n        # 5. 综合分析\n        print(\"\\n=== 综合周期分析 ===\")\n        \n        # 计算加权综合得分\n        weighted_score = 0\n        total_weight = 0\n        \n        for cycle_name, strength in cycle_strength.items():\n            weighted_score += strength['最近值'] * strength['权重']\n            total_weight += strength['权重']\n        \n        if total_weight > 0:\n            composite_score = weighted_score / total_weight\n            print(f\"综合周期得分: {composite_score:.4f}\")\n            \n            if composite_score > 0.01:\n                print(\"综合判断: 美元指数处于相对强势周期\")\n            elif composite_score < -0.01:\n                print(\"综合判断: 美元指数处于相对弱势周期\")\n            else:\n                print(\"综合判断: 美元指数处于相对平衡状态\")\n        \n        print(\"\\n分析完成！\")\n\nif __name__ == \"__main__\":\n    # 运行分析\n    analyzer = DollarIndexCycleAnalysis()\n    analyzer.run_analysis() 